class Solution:
    def groupAnagrams(self, strs: List[str]) -> List[List[str]]:
        hmap = collections.defaultdict(list)
        for str in strs:
            alpha = [0] * 26
            for ch in str:
                alpha[ord(ch) - ord('a')] += 1

            hmap[tuple(alpha)].append(str)

        return list(hmap.values())
